import{_ as o,l,o as a,c as s,v as t,p as n,x as r,d,i as u,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"队列与缓冲","description":"","frontmatter":{"title":"队列与缓冲","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/queue-buffer.md","filePath":"cs/queue-buffer.md","lastUpdated":1789023840000}'),c={name:"cs/queue-buffer.md"};function h(f,e,m,_,q,T){const i=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="队列与缓冲" tabindex="-1">队列与缓冲 <a class="header-anchor" href="#队列与缓冲" aria-label="Permalink to &quot;队列与缓冲&quot;">​</a></h1><div class="epigraph"><p>一端进、一端出，先来的先被服务；流水线与生产者-消费者要的是这个纪律，不是 LIFO。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/stack-adt">上一课</a>把一端操作钉成 LIFO，并对齐调用帧。<a href="/cs/stack-adt">流水线五级</a>里指令按取指序前进，ROB 也是按序提交的队列。<a href="/cs/superscalar-issue">超标量发射</a>的发射窗口不是栈。本课不重讲 push/pop。缺口是 FIFO：enqueue 与 dequeue 分属两端，用来做缓冲而不是做嵌套寿命。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栈会把后到的任务先处理，公平的等待线和流式缓冲都不允许。缺口不是新的节点类型，而是合同：抽象状态仍是序列，进尾出头。空出、满进无定义或返回失败。</p><p>循环数组用头尾下标模 \\(n\\)，避免每次 dequeue 搬移整块——那是数组插入的教训。链表队列用头尾两个指针，两端 \\(\\Theta(1)\\)。本课两种表示都合法。</p><p><span class="marginnote">有界队列把背压写成「满则生产者停」。无界队列把背压推到内存耗尽。实时系统通常要有界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>操作：enqueue、dequeue、队头窥视。代价：两种主表示下均为 \\(\\Theta(1)\\) 最坏（定容数组）或 \\(\\Theta(1)\\) 最坏（链表）。顺序与栈相反：先入先出。</p>',9)),(a(),n(p,null,{default:r(()=>[u(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22enqueue%20%E5%B0%BE%22%5D%20--%3E%20Q%5B%22%E5%BA%8F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20OUT%5B%22dequeue%20%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>环形缓冲：<code>tail = (tail+1) mod cap</code>。空与满用计数或浪费一个槽区分。这是实现细节，合同只看见 FIFO。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓冲把速率不同的两端解开：IF 取指快于 EX 时，中间的队列（或流水线寄存器链）托住气泡之外的指令流。软件上，日志、消息、BFS 的frontier 都是队列。BFS 后课才用；本课只把结构备好。</p><p>与<a href="/cs/locality-principle">局部性原理</a>：环形数组顺序走，cache 友好；链表队列又回到指针追逐。高吞吐缓冲选数组。流水线寄存器是深度固定的队列；软件环形缓冲只是把深度做成参数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入优先队列——那是堆课，合同按键而不是按到达序。也不写无锁 Michael–Scott 队列。双端队列允许两端进出，合同更宽，主干不提前。</p><p>后课默认：缓冲 = FIFO 队列。数组环形是高性能默认表示。扩容数组的「偶尔 \\(\\Theta(n)\\) 复制」还没有分析方法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>队列是 FIFO，两端操作；栈是 LIFO，一端操作。</li><li>环形数组或头尾链表均可 \\(\\Theta(1)\\)；局部性偏向数组。</li><li>倍增扩容的平均代价是下一课摊还。</li><li>优先队列按键不按到达序，那是堆课。</li><li>有界队列把背压写成满则停；无界把背压推到内存。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 队列。</li></ul>',9))])}const B=o(c,[["render",h]]);export{F as __pageData,B as default};
